use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::String(s) = input {
        let trimmed = s.trim();
        let words: Vec<&str> = trimmed.split_whitespace().collect();
        let joined: String = words.join(" ");
        Value::String(joined)
    } else {
        input
    }
}
